package com.eilo.foundation
import org.junit.Assert.*
import org.junit.Test
class GenericReplacementTest {
    private fun controller():NativeController=NativeController(effects=object:ControllerEffects{
        override fun startCapture()=true;override fun playClause(clause:String){fail("legacy speech must not run")};override fun cancelWork(){};override fun releaseCapture(){};override fun clearVolatileContext(){}
    },permission=object:MicrophonePermissionAdapter{override fun status()=MicrophonePermission.GRANTED;override fun request(completion:(MicrophonePermission)->Unit){completion(status())}},models=ModelReadinessAdapter{ModelStatus.READY}).apply{
        assertTrue(dispatch(ControllerEvent.START));assertTrue(dispatch(ControllerEvent.SPEECH_DETECTED,token=token()));assertTrue(dispatch(ControllerEvent.ENDPOINT,token=token()))
    }

    private class Sink:NativeClauseSink {val texts=mutableListOf<String>();val callbacks=mutableListOf<(OfflineSpeechEvent)->Unit>();var stops=0;override fun enqueue(token:GenerationToken,text:String,event:(OfflineSpeechEvent)->Unit):Boolean{texts+=text;callbacks+=event;return true};override fun cancel(){stops++}}
    private fun activation(token:GenerationToken):InterruptionActivation {val vad=ConfirmedSpeechInterruption(token);var event:InterruptionActivation?=null;repeat(8){event=vad.advance(1f,true)};return event!!}
    @Test fun oldSpeechCancelledBeforeExactlyOneReplacement(){val time=FakeTime();val c=testController(clock=time,scheduler=time);val s=Sink();assertTrue(c.dispatch(ControllerEvent.START));assertTrue(c.dispatch(ControllerEvent.SPEECH_DETECTED,token=c.token()));val old=c.token()!!;var receive:((ByteArray,Int)->Unit)?=null;var finish:((LlmJobResult)->Unit)?=null;val first=GenericSpokenTurn(c,old,s,true,GenericReplyStarter{_,_,r,f->receive=r;finish=f;val b="First. Second. ".toByteArray();r(b,b.size);true});assertTrue(first.submit(AsrText("Hello.",true),1f));s.callbacks[0](OfflineSpeechEvent.STARTED);val event=activation(old);var starts=0;val replacement=GenericSpokenTurn.replacing(event,c,s,true,{true},GenericReplyStarter{_,request,r,f->starts++;assertTrue(request.history.isEmpty());val b="Blue.".toByteArray();r(b,b.size);f(LlmJobResult.COMPLETED);true})!!;assertTrue(old.cancelled);assertTrue(s.stops>0);assertTrue(c.recognitionAllowed(c.token()!!));assertFalse(c.recognitionAllowed(old));assertNull(event.apply(c){true});assertTrue(replacement.submit(AsrText("Name one colour.",true),1f));assertFalse(replacement.submit(AsrText("Duplicate.",true),1f));try{val b="Stale.".toByteArray();receive!!(b,b.size);fail("stale accepted")}catch(_:IllegalStateException){};finish!!(LlmJobResult.COMPLETED);s.callbacks[0](OfflineSpeechEvent.FINISHED);assertEquals(listOf("First.","Blue."),s.texts);s.callbacks[1](OfflineSpeechEvent.STARTED);s.callbacks[1](OfflineSpeechEvent.FINISHED);assertEquals(ControllerState.STANDBY,c.state());assertEquals(1,starts)}
    @Test fun defaultAndLostSeparationCannotCapture(){val c=controller();val s=Sink();val old=c.token()!!;val q=NativeClauseQueue.create(c,old,s){_,_->true}!!;q.enqueue("First.");s.callbacks[0](OfflineSpeechEvent.STARTED);val event=activation(old);assertNull(GenericSpokenTurn.replacing(event,c,s));assertNull(GenericSpokenTurn.replacing(event,c,s,true));assertFalse(old.cancelled);var verified=true;val next=event.apply(c){verified}!!;assertTrue(c.recognitionAllowed(next));verified=false;assertFalse(c.recognitionAllowed(next));c.stop();verified=true;assertFalse(c.recognitionAllowed(next))}
    @Test fun appOutputVadAndPrivacyCannotReplace(){val c=controller();val old=c.token()!!;val vad=ConfirmedSpeechInterruption(old);repeat(100){assertNull(vad.advance(1f,false))};val event=activation(old);c.privacyTransition(PrivacyChange.LOCK);assertNull(event.apply(c){true});assertEquals(ControllerState.STOPPED,c.state())}
}
